// 1. instanceof 模式匹配（Java 16+）
if (obj instanceof String s && s.length() > 5) {
    System.out.println(s.toUpperCase());
}
// s 只在编译器能证明匹配成功的作用域内可用

// 2. switch 类型模式 + sealed 穷举（Java 21）
sealed interface Shape permits Circle, Rect {}
record Circle(double r) implements Shape {}
record Rect(double w, double h) implements Shape {}

static String describe(Shape shape) {
    return switch (shape) {
        case Circle c when c.r() > 10 -> "大圆，半径=" + c.r();
        case Circle c -> "小圆，半径=" + c.r();
        case Rect(double w, double h) -> "矩形，面积=" + w * h;
    };
}

// 3. null 必须显式处理或由 default/异常策略覆盖
static String safeCheck(Object obj) {
    return switch (obj) {
        case null -> "null 值";
        case String s -> "字符串: " + s;
        case Integer i -> "整数: " + i;
        default -> "其他类型";
    };
}
